package com.platform.learning.web;
import com.platform.family.service.FamilyAccessGuard; import com.platform.learning.entity.ActivityAttemptStatus; import com.platform.learning.repository.ActivityAttemptRepository; import com.platform.learning.repository.EnrollmentRepository; import com.platform.learning.repository.LearningPathRepository; import com.platform.learning.repository.LearningPathItemRepository; import com.platform.streak.service.LearnerStreakService; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/children/{childId}/progress") public class LearnerProgressController {
 private final FamilyAccessGuard guard; private final ActivityAttemptRepository attempts; private final LearnerStreakService streaks; private final EnrollmentRepository enrollments; private final LearningPathRepository paths; private final LearningPathItemRepository items;
 public LearnerProgressController(FamilyAccessGuard g,ActivityAttemptRepository a,LearnerStreakService s,EnrollmentRepository e,LearningPathRepository p,LearningPathItemRepository i){guard=g;attempts=a;streaks=s;enrollments=e;paths=p;items=i;}
 @GetMapping public Response get(@PathVariable UUID childId,@AuthenticationPrincipal UUID id){guard.requireChildAccess(id,childId);var all=attempts.findByChildIdOrderByStartedAtDesc(childId);var completed=all.stream().filter(a->a.getStatus()==ActivityAttemptStatus.COMPLETED).toList();long seconds=completed.stream().filter(a->a.getCompletedAt()!=null).mapToLong(a->Duration.between(a.getStartedAt(),a.getCompletedAt()).getSeconds()).sum();var s=streaks.get(childId);long total=0,done=0;for(var e:enrollments.findByChildId(childId)){var path=paths.findByEnrollmentId(e.getId());if(path.isPresent()){var its=items.findByLearningPathIdOrderBySequenceOrderAsc(path.get().getId());total+=its.size();done+=its.stream().filter(x->x.getStatus()==com.platform.learning.entity.LearningPathItemStatus.COMPLETED).count();}}return new Response(childId,completed.size(),seconds/60,s.getCurrentStreak(),s.getLongestStreak(),done,total);}
 public record Response(UUID childId,long completedActivities,long learningMinutes,int currentStreak,int longestStreak,long completedPathItems,long totalPathItems){}
}
